import{_ as a,C as i,c as l,o as g,a3 as n,G as r,j as t,a as s}from"./chunks/framework.Dokpd4od.js";const P=JSON.parse('{"title":"Set up a register","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/get-started/set-up-a-register.md","filePath":"master/sales/point-of-sale/get-started/set-up-a-register.md","lastUpdated":1791902625000}'),c={name:"master/sales/point-of-sale/get-started/set-up-a-register.md"};function u(d,e,p,h,m,f){const o=i("ImagePopup");return g(),l("div",null,[e[5]||(e[5]=n('<h1 id="set-up-a-register" tabindex="-1">Set up a register <a class="header-anchor" href="#set-up-a-register" aria-label="Permalink to &quot;Set up a register&quot;">​</a></h1><p>A register is one till, such as the counter of a shop or the floor of a restaurant. Its form holds every rule for that till: which payment methods it takes, how prices show, what receipts say and where stock comes from. You build the register once, then open a session on it each day.</p><blockquote><p><strong>In simple words:</strong> A register is a till with its own rules. Fill in its form once, then sell.</p></blockquote><p>Before you start, create the items the register needs: <a href="./../payments-setup/payment-methods.html">payment methods</a>, <a href="./../payments-setup/coins-and-bills.html">coins and bills</a> and, for a restaurant, <a href="./../payments-setup/restaurant-floors-and-notes.html">floors</a>.</p><h2 id="the-register-list" tabindex="-1">The register list <a class="header-anchor" href="#the-register-list" aria-label="Permalink to &quot;The register list&quot;">​</a></h2><p>Go to <code>Point of Sale → Configurations → Point of Sale</code>. The list shows each register with <strong>Name</strong>, <strong>Code</strong>, <strong>Closing</strong>, <strong>Balance</strong>, <strong>Active</strong> and <strong>Company</strong>. Tabs split the list into <strong>Default</strong>, <strong>Active</strong>, <strong>Restaurant</strong> and <strong>Archived</strong>. You can group rows by <strong>Warehouse</strong> or <strong>Company</strong>.</p>',6)),r(o,{src:"/images1/pos/register_list.png",alt:"Point of Sale register list showing Spice Route Kitchen & Bar (SRK) and TechNest Electronics (TNE)"}),e[6]||(e[6]=t("h2",{id:"create-a-register",tabindex:"-1"},[s("Create a register "),t("a",{class:"header-anchor",href:"#create-a-register","aria-label":'Permalink to "Create a register"'},"​")],-1)),t("ol",null,[e[1]||(e[1]=t("li",null,[t("p",null,[s("Go to "),t("code",null,"Point of Sale → Configurations → Point of Sale"),s(".")])],-1)),e[2]||(e[2]=t("li",null,[t("p",null,[s("Click "),t("strong",null,"New Point of Sale"),s(".")])],-1)),t("li",null,[e[0]||(e[0]=n("<p>Fill the <strong>General</strong> section.</p><ul><li><strong><em>Point of Sale:</em></strong> The register name, for example <strong>TechNest Electronics</strong>.</li><li><strong><em>Short Code:</em></strong> A prefix of up to 16 characters, for example <strong>TNE</strong>. POS uses it for order and session numbers.</li></ul>",2)),r(o,{src:"/images1/pos/register_create_general.png",alt:"New Point of Sale form with Point of Sale set to TechNest Electronics and Short Code set to TNE"})]),e[3]||(e[3]=t("li",null,[t("p",null,[s("Click "),t("strong",null,"Create"),s(". The page reopens with the "),t("strong",null,"Configurations"),s(" section and its tabs.")])],-1)),e[4]||(e[4]=t("li",null,[t("p",null,[s("Fill each tab as described below, then click "),t("strong",null,"Save changes"),s(".")])],-1))]),e[7]||(e[7]=t("h2",{id:"the-configuration-tabs",tabindex:"-1"},[s("The configuration tabs "),t("a",{class:"header-anchor",href:"#the-configuration-tabs","aria-label":'Permalink to "The configuration tabs"'},"​")],-1)),e[8]||(e[8]=t("p",null,[s("The tabs run down the left side of the "),t("strong",null,"Configurations"),s(" section.")],-1)),r(o,{src:"/images1/pos/register_edit_tabs.png",alt:"Register edit page with the tab list: Restaurant Mode, Payment, PoS Interface, Product and PoS categories, Accounting, Pricing, Bills and Receipts, Preparation, Inventory"}),e[9]||(e[9]=n('<h3 id="restaurant-mode" tabindex="-1">Restaurant Mode <a class="header-anchor" href="#restaurant-mode" aria-label="Permalink to &quot;Restaurant Mode&quot;">​</a></h3><ul><li><strong><em>Is a Bar/Restaurant:</em></strong> Turns on tables, split bills and preparation tickets. Keep it off for a shop.</li><li><strong><em>Allow Bill Splitting:</em></strong> Lets the cashier split the total or order lines.</li><li><strong><em>Early Receipt Printing:</em></strong> Lets the cashier print a receipt before payment.</li><li><strong><em>Eat in / Take out:</em></strong> Changes the tax rate by service type. A new field, <strong>Alternative Fiscal Position</strong>, then appears. Pick the position used for take out.</li><li><strong><em>Floors &amp; Tables Map:</em></strong> The floors for this register, such as <strong>Ground Floor</strong> and <strong>Rooftop Lounge</strong>.</li></ul><p>The last four options show only when <strong>Is a Bar/Restaurant</strong> is on.</p>',3)),r(o,{src:"/images1/pos/register_tab_restaurant.png",alt:"Restaurant Mode tab of Spice Route Kitchen & Bar with all toggles on and Ground Floor and Rooftop Lounge selected"}),e[10]||(e[10]=n('<h3 id="payment" tabindex="-1">Payment <a class="header-anchor" href="#payment" aria-label="Permalink to &quot;Payment&quot;">​</a></h3><ul><li><strong><em>Payment Methods:</em></strong> The methods the cashier can choose, such as Cash or Bank.</li><li><strong><em>Set Maximum Difference:</em></strong> Limits the gap allowed between expected and counted money at closing. Then enter <strong>Maximum Difference</strong>.</li><li><strong><em>Cash Rounding:</em></strong> Rounds cash payments to the smallest coin. Then pick a <strong>Rounding Method</strong>. Turn on <strong>Only apply rounding on cash</strong> to leave other methods exact.</li><li><strong><em>Tips:</em></strong> Lets the cashier accept tips. Then pick a <strong>Tip Product</strong>, which must be a service.</li></ul>',2)),r(o,{src:"/images1/pos/register_tab_payment.png",alt:"Payment tab with Cash and Bank payment methods selected and Tips turned on with a Tip Product"}),e[11]||(e[11]=n('<h3 id="pos-interface" tabindex="-1">PoS Interface <a class="header-anchor" href="#pos-interface" aria-label="Permalink to &quot;PoS Interface&quot;">​</a></h3><ul><li><strong><em>Customer Required:</em></strong> The cashier must pick a customer before payment.</li><li><strong><em>Show product images:</em></strong> Shows pictures on product tiles.</li><li><strong><em>Show category images:</em></strong> Shows pictures on category tiles.</li><li><strong><em>Products Loaded:</em></strong> How many products load when a session opens. The default is 500.</li></ul>',2)),r(o,{src:"/images1/pos/register_tab_interface.png",alt:"PoS Interface tab with product images and category images on and Products Loaded set to 500"}),e[12]||(e[12]=t("h3",{id:"product-pos-categories",tabindex:"-1"},[s("Product & PoS categories "),t("a",{class:"header-anchor",href:"#product-pos-categories","aria-label":'Permalink to "Product & PoS categories"'},"​")],-1)),e[13]||(e[13]=t("ul",null,[t("li",null,[t("strong",null,[t("em",null,"Show margins & costs:")]),s(" Shows margin and cost on product information.")]),t("li",null,[t("strong",null,[t("em",null,"Restrict Categories:")]),s(" Limits the register to chosen categories. Then pick them in "),t("strong",null,"Available PoS Product Categories"),s(".")])],-1)),r(o,{src:"/images1/pos/register_tab_categories.png",alt:"Product and PoS categories tab with Restrict Categories on and Accessories and Audio selected"}),e[14]||(e[14]=n('<h3 id="accounting" tabindex="-1">Accounting <a class="header-anchor" href="#accounting" aria-label="Permalink to &quot;Accounting&quot;">​</a></h3><ul><li><strong><em>Orders Journal:</em></strong> The journal for the session closing entry.</li><li><strong><em>Invoices Journal:</em></strong> The sales journal for invoices made from POS orders.</li><li><strong><em>Closing Entry by product:</em></strong> Lists sales by product in the closing entry.</li><li><strong><em>Flexible Taxes:</em></strong> Lets orders use different <a href="./../../../finance/taxes/fiscal-positions.html">fiscal positions</a>. Then pick a <strong>Default Fiscal Position</strong> and the allowed <strong>Fiscal Positions</strong>.</li><li><strong><em>Intermediary Account:</em></strong> Receivable account used between payment and closing. Leave empty to use the default from <a href="./pos-settings.html">POS settings</a>.</li><li><strong><em>Cash In/Out Account:</em></strong> Account for cash moved in or out of the drawer.</li><li><strong><em>Balancing Account:</em></strong> Account for a cash difference at closing.</li><li><strong><em>Cost of Goods Sold:</em></strong> Posts the cost of sold items when you close. Then pick a <strong>Cost of Goods Sold Journal</strong> and a <strong>Stock Output Account</strong>.</li></ul>',2)),r(o,{src:"/images1/pos/register_tab_accounting.png",alt:"Accounting tab with Orders Journal, Invoices Journal and the cash in and out account filled in"}),e[15]||(e[15]=n('<h3 id="pricing" tabindex="-1">Pricing <a class="header-anchor" href="#pricing" aria-label="Permalink to &quot;Pricing&quot;">​</a></h3><ul><li><strong><em>Product Prices:</em></strong> Choose <strong>Tax Excluded</strong> or <strong>Tax Included</strong>. This sets how prices show on the terminal and receipts.</li><li><strong><em>Price Control:</em></strong> Only managers can change a price.</li><li><strong><em>Flexible Pricelists:</em></strong> Allows several price lists. Pick the <strong>Available Pricelists</strong>.</li><li><strong><em>Default Pricelist:</em></strong> The list applied to every order. Cashiers can switch lists only when flexible pricelists are on.</li><li><strong><em>Line Discounts:</em></strong> Cashiers can give a discount on one line.</li><li><strong><em>Global Discounts:</em></strong> Adds a button for a whole-order discount. Then pick a <strong>Discount Product</strong> (a service) and the default <strong>Discount %</strong>.</li></ul>',2)),r(o,{src:"/images1/pos/register_tab_pricing.png",alt:"Pricing tab with Product Prices set to Tax Included, Line Discounts on and Global Discounts on at 10 percent"}),e[16]||(e[16]=n('<h3 id="bills-receipts" tabindex="-1">Bills &amp; Receipts <a class="header-anchor" href="#bills-receipts" aria-label="Permalink to &quot;Bills &amp; Receipts&quot;">​</a></h3><ul><li><strong><em>Receipt Printing:</em></strong> Shows a <strong>Print</strong> button on the receipt screen.</li><li><strong><em>Automatic Receipt Printing:</em></strong> Prints the receipt as soon as payment is registered.</li><li><strong><em>Receipt Header:</em></strong> Text at the top of the receipt, for example your shop address.</li><li><strong><em>Receipt Footer:</em></strong> Text at the bottom, for example &quot;Thank you for shopping at TechNest&quot;.</li><li><strong><em>Coins/Bills:</em></strong> The denominations offered when counting cash at opening and closing.</li></ul>',2)),r(o,{src:"/images1/pos/register_tab_receipts.png",alt:"Bills and Receipts tab with receipt printing on, header and footer text, and coin and bill denominations selected"}),e[17]||(e[17]=t("h3",{id:"preparation",tabindex:"-1"},[s("Preparation "),t("a",{class:"header-anchor",href:"#preparation","aria-label":'Permalink to "Preparation"'},"​")],-1)),e[18]||(e[18]=t("ul",null,[t("li",null,[t("strong",null,[t("em",null,"Preparation Printers:")]),s(" The printers that receive kitchen or bar tickets. See "),t("a",{href:"./../payments-setup/preparation-printers.html"},"Preparation printers"),s(".")])],-1)),r(o,{src:"/images1/pos/register_tab_preparation.png",alt:"Preparation tab with a Kitchen printer selected"}),e[19]||(e[19]=n('<h3 id="inventory" tabindex="-1">Inventory <a class="header-anchor" href="#inventory" aria-label="Permalink to &quot;Inventory&quot;">​</a></h3><ul><li><strong><em>Warehouse:</em></strong> The warehouse stock comes from. Required.</li><li><strong><em>Operation Type:</em></strong> The outgoing operation used to record product pickings.</li><li><strong><em>Return Operation Type:</em></strong> The incoming operation used for returns.</li><li><strong><em>Allow Ship Later:</em></strong> Sell now and deliver later. Then choose a <strong>Specific Route</strong> and a <strong>Shipping Policy</strong>: <strong>As soon as possible</strong> or <strong>When all products are ready</strong>.</li></ul>',2)),r(o,{src:"/images1/pos/register_tab_inventory.png",alt:"Inventory tab with Warehouse, Operation Type and Return Operation Type filled in"}),e[20]||(e[20]=n('<h2 id="two-worked-examples" tabindex="-1">Two worked examples <a class="header-anchor" href="#two-worked-examples" aria-label="Permalink to &quot;Two worked examples&quot;">​</a></h2><p><strong>TechNest Electronics (retail).</strong> Leave <strong>Is a Bar/Restaurant</strong> off. Pick Cash and Bank. Turn on <strong>Customer Required</strong> and <strong>Line Discounts</strong>. Set <strong>Product Prices</strong> to <strong>Tax Included</strong> and choose the main warehouse.</p><p><strong>Spice Route Kitchen &amp; Bar (restaurant).</strong> Turn on <strong>Is a Bar/Restaurant</strong>, <strong>Allow Bill Splitting</strong> and <strong>Early Receipt Printing</strong>. Pick <strong>Ground Floor</strong> and <strong>Rooftop Lounge</strong>. Add a kitchen printer in <strong>Preparation</strong>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Open Terminal:</strong> In the page header. It opens the cashier terminal for this register.</li><li><strong>Save changes:</strong> Saves the form.</li><li><strong>Delete:</strong> Archives the register. A register with sessions or orders cannot be deleted permanently, so archive it.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>While a session is open, these fields are locked: <strong>Is a Bar/Restaurant</strong>, <strong>Payment Methods</strong>, <strong>Restrict Categories</strong>, <strong>Available PoS Product Categories</strong> and <strong>Global Discounts</strong>. Close the session to change them.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Before the first session, POS checks the register. It needs a receivable account, payment methods, a cash journal and tax accounts. A missing item stops the session from opening.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./pos-settings.html">POS settings</a></li><li><a href="./../sessions/open-register.html">Open a register</a></li><li><a href="./../payments-setup/payment-methods.html">Payment methods</a></li></ul>',9))])}const _=a(c,[["render",u]]);export{P as __pageData,_ as default};
